import fs from "node:fs";
import path from "node:path";
import { buildPack, slug, type PackIndex, type PackItem, type PNode } from "../../shared/src/rbxm/pack.js";
import type { Logger } from "./logger.js";

/**
 * Asset packs on the bridge side:
 *  - bundled packs: <base>/packs/built/<id>.json (generated by scripts/gen-packs.ts from packs/src/*.rbxm)
 *  - user packs:    <data>/packs/*.rbxm and <base>/packs/user/*.rbxm (parsed + auto-named at load, cached by mtime)
 * The AI searches them with the brickwire_assets tool and places items with BW.asset("pack/item", {...});
 * the bridge injects the build data of every asset id written literally in the Luau code.
 */
export interface LoadedPack {
  index: PackIndex;
  data: Record<string, PNode>;
  source: "bundled" | "user";
  file: string;
}

export interface AssetHit {
  id: string;
  name: string;
  kind: string;
  category: string;
  size: number[];
  parts?: number;
  scripts?: number;
  fx?: number;
  original?: string;
}

const ID_RE = /^[a-z0-9_]+\/[a-z0-9_]+$/;
/** Max Luau data injected per execute_luau call (bigger calls must be split). */
export const ASSET_INJECT_LIMIT = 900_000;

export class AssetLibrary {
  packs = new Map<string, LoadedPack>();
  private byId = new Map<string, { pack: LoadedPack; item: PackItem }>();
  private userMtimes = new Map<string, number>();
  private loadedAt = 0;

  private dirs: { bundled: string[]; user: string[] };
  private logger?: Logger;
  constructor(dirs: { bundled: string[]; user: string[] }, logger?: Logger) {
    this.dirs = dirs;
    this.logger = logger;
  }

  /** (Re)load packs; user packs are re-checked at most every 5 s. */
  load(force = false): this {
    if (!force && this.loadedAt && Date.now() - this.loadedAt < 5000) return this;
    const first = !this.loadedAt;
    this.loadedAt = Date.now();
    if (first || force) {
      for (const dir of this.dirs.bundled) {
        let files: string[] = [];
        try {
          files = fs.readdirSync(dir).filter((f) => f.endsWith(".json") && !f.endsWith(".tiles.json"));
        } catch {
          continue;
        }
        for (const f of files) {
          try {
            const b = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8")) as { index: PackIndex; data: Record<string, PNode> };
            if (!b?.index?.id || !Array.isArray(b.index.items)) continue;
            this.add({ index: b.index, data: b.data, source: "bundled", file: path.join(dir, f) });
          } catch (e) {
            this.logger?.warn("assets.load_failed", `${f}: ${(e as Error).message}`);
          }
        }
      }
    }
    for (const dir of this.dirs.user) {
      let files: string[] = [];
      try {
        files = fs.readdirSync(dir).filter((f) => /\.rbxm$/i.test(f));
      } catch {
        continue;
      }
      for (const f of files) {
        const file = path.join(dir, f);
        let mt = 0;
        try {
          mt = fs.statSync(file).mtimeMs;
        } catch {
          continue;
        }
        if (this.userMtimes.get(file) === mt) continue;
        this.userMtimes.set(file, mt);
        try {
          let id = slug(path.basename(f, path.extname(f))).slice(0, 24) || "user";
          if (this.packs.has(id) && this.packs.get(id)!.file !== file) id = `user_${id}`;
          const t0 = Date.now();
          const b = buildPack(new Uint8Array(fs.readFileSync(file)), { id, file: f, title: path.basename(f, path.extname(f)), description: `User pack (${f})`, skip: [] });
          this.add({ index: b.index, data: b.data, source: "user", file });
          this.logger?.info("assets.user_pack", `${f} → ${id}: ${b.index.items.length} items (${Date.now() - t0} ms)`);
        } catch (e) {
          this.logger?.warn("assets.user_pack_failed", `${f}: ${(e as Error).message}`);
        }
      }
    }
    return this;
  }

  private add(p: LoadedPack) {
    const old = this.packs.get(p.index.id);
    if (old) for (const it of old.index.items) this.byId.delete(it.id);
    this.packs.set(p.index.id, p);
    for (const item of p.index.items) this.byId.set(item.id, { pack: p, item });
  }

  get count(): number {
    return this.byId.size;
  }

  get(id: string): { pack: LoadedPack; item: PackItem; node: PNode } | null {
    const e = this.byId.get(id) ?? this.byId.get(this.normalizeId(id) ?? "");
    if (!e) return null;
    const node = e.pack.data[e.item.id];
    return node ? { ...e, node } : null;
  }

  /** "VFX/Shockwave", "vfx/shockwave ", "vfx:shockwave" → "vfx/shockwave"; also a bare unique slug ("shockwave_ring"). */
  normalizeId(raw: string): string | null {
    const s = raw.trim().toLowerCase().replace(/[:\\]/, "/").replace(/[\s-]+/g, "_");
    if (this.byId.has(s)) return s;
    if (!s.includes("/")) {
      const hits = [...this.byId.keys()].filter((k) => k.endsWith("/" + s));
      if (hits.length === 1) return hits[0]!;
    }
    return null;
  }

  /** Ranked search over names, tags, categories, original names. */
  search(q: { query?: string; pack?: string; kind?: string; category?: string; limit?: number; offset?: number }): { total: number; items: AssetHit[] } {
    this.load();
    const words = (q.query ?? "")
      .toLowerCase()
      .split(/[^a-z0-9а-яё]+/i)
      .filter((w) => w.length > 1);
    const pack = q.pack?.toLowerCase();
    const kind = q.kind?.toLowerCase();
    const cat = q.category?.toLowerCase();
    const scored: Array<[number, PackItem]> = [];
    for (const { item, pack: p } of this.byId.values()) {
      if (pack && p.index.id !== pack) continue;
      if (kind && item.kind !== kind) continue;
      if (cat && !item.category.toLowerCase().includes(cat)) continue;
      let score = 0;
      if (words.length) {
        const name = item.name.toLowerCase();
        const hay = [name, item.category.toLowerCase(), item.original.toLowerCase(), item.tags.join(" "), item.id].join(" ");
        for (const w of words) {
          const stem = w.length > 4 ? w.slice(0, -1) : w;
          if (name.split("_").includes(w)) score += 5;
          else if (name.includes(stem)) score += 3;
          else if (hay.includes(stem)) score += 1.5;
          else score -= 2;
        }
        if (score <= 0) continue;
        score -= item.name.length / 200; // prefer short exact names
      }
      scored.push([score, item]);
    }
    scored.sort((a, b) => b[0] - a[0]);
    const off = Math.max(0, q.offset ?? 0);
    const lim = Math.min(200, Math.max(1, q.limit ?? 25));
    return { total: scored.length, items: scored.slice(off, off + lim).map(([, it]) => hit(it)) };
  }

  /** Closest ids for an unknown one (for "did you mean"). */
  suggest(raw: string, n = 5): string[] {
    const words = raw.toLowerCase().replace(/^[a-z0-9_]+\//, "").replace(/_/g, " ");
    const pack = raw.includes("/") ? raw.split("/")[0]!.toLowerCase() : undefined;
    let r = this.search({ query: words, pack: pack && this.packs.has(pack) ? pack : undefined, limit: n }).items;
    if (!r.length && pack) r = this.search({ query: words, limit: n }).items;
    return r.map((x) => x.id);
  }

  overview() {
    this.load();
    return [...this.packs.values()].map((p) => ({
      id: p.index.id,
      title: p.index.title,
      description: p.index.description,
      source: p.source,
      items: p.index.items.length,
      categories: Object.fromEntries(Object.entries(p.index.categories).slice(0, 40)),
    }));
  }

  /** Short outline of an item's instance tree (for the AI to see what it gets). */
  outline(node: PNode, depth = 0, out: string[] = [], max = 40): string[] {
    if (out.length >= max) return out;
    out.push(`${"  ".repeat(depth)}${node.n} (${node.c})`);
    for (const k of node.k ?? []) this.outline(k, depth + 1, out, max);
    return out;
  }

  /**
   * Luau statements (ONE line) defining BW.__assetData for every pack id written literally in `code`,
   * and BW.__assetMiss suggestions for unknown ones. Returns null when the code references no asset ids.
   */
  injectionFor(code: string): { luau: string; ids: string[]; missing: string[]; bytes: number } | null {
    this.load();
    const refs = new Set<string>();
    for (const m of code.matchAll(/["']([A-Za-z0-9_]+[/:][A-Za-z0-9_ -]+)["']/g)) refs.add(m[1]!);
    if (!refs.size) return null;
    const found = new Map<string, { item: PackItem; node: PNode; pack: LoadedPack }>();
    const missing: string[] = [];
    const aliases: Array<[string, string]> = [];
    const asked = /BW\s*[.:]\s*asset(?:Info)?\s*\(/.test(code);
    for (const r of refs) {
      const e = this.get(r);
      if (e) {
        found.set(e.item.id, e);
        if (e.item.id !== r) aliases.push([r, e.item.id]);
      } else if (asked && this.packs.has(r.split(/[/:]/)[0]!.toLowerCase())) missing.push(r);
    }
    if (!found.size && !missing.length) return null;
    const parts: string[] = [];
    let bytes = 0;
    for (const [id, { item, node, pack }] of found) {
      const rec = `BW.__assetData[${lstr(id)}]={k=${lstr(item.kind)},s={${item.size.map(num).join(",")}},r=${lstr(pack.index.root)},path=${lstr(item.path)}${item.merged ? ",merged=true" : ""},d=${lnode(node)}}`;
      bytes += rec.length;
      parts.push(rec);
    }
    if (bytes > ASSET_INJECT_LIMIT) throw new Error(`too much asset data in one execute_luau call (${Math.round(bytes / 1024)} KB > ${Math.round(ASSET_INJECT_LIMIT / 1024)} KB): place fewer different assets per call (split into several calls)`);
    for (const [from, to] of aliases) parts.push(`BW.__assetData[${lstr(from)}]=BW.__assetData[${lstr(to)}]`);
    for (const m of missing) parts.push(`BW.__assetMiss[${lstr(m)}]=${lstr(this.suggest(m).join(", ") || "nothing similar")}`);
    return { luau: "BW.__assetData=BW.__assetData or {} BW.__assetMiss=BW.__assetMiss or {} " + parts.join(" "), ids: [...found.keys()], missing, bytes };
  }
}

function hit(it: PackItem): AssetHit {
  const h: AssetHit = { id: it.id, name: it.name, kind: it.kind, category: it.category, size: it.size.map((x) => Math.round(x * 100) / 100) };
  if (it.parts > 1) h.parts = it.parts;
  if (it.scripts) h.scripts = it.scripts;
  if (it.fx) h.fx = it.fx;
  if (it.renamed) h.original = it.original;
  return h;
}

export function isAssetId(s: string): boolean {
  return ID_RE.test(s);
}

// ---------------------------------------------------------------- compact Luau literal writer (single line)
function num(n: number): string {
  if (!Number.isFinite(n)) return "0";
  if (Number.isInteger(n)) return String(n);
  const s = String(Math.round(n * 1e6) / 1e6);
  return s === "-0" ? "0" : s;
}

export function lstr(s: string): string {
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0)!;
    if (ch === "\\") out += "\\\\";
    else if (ch === '"') out += '\\"';
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (c < 0x20 || c === 0x7f) out += "\\" + String(c).padStart(3, "0");
    else out += ch;
  }
  return out + '"';
}

const IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;
const RESERVED = new Set("and break do else elseif end false for function if in local nil not or repeat return then true until while continue".split(" "));
function key(k: string): string {
  return IDENT.test(k) && !RESERVED.has(k) ? k : `[${lstr(k)}]`;
}

function lval(v: unknown): string {
  if (v === null || v === undefined) return "nil";
  if (typeof v === "boolean") return v ? "true" : "false";
  if (typeof v === "number") return num(v);
  if (typeof v === "string") return lstr(v);
  if (Array.isArray(v)) return "{" + v.map(lval).join(",") + "}";
  if (typeof v === "object") {
    return (
      "{" +
      Object.entries(v as Record<string, unknown>)
        .filter(([, x]) => x !== undefined)
        .map(([k, x]) => `${key(k)}=${lval(x)}`)
        .join(",") +
      "}"
    );
  }
  return "nil";
}

export function lnode(n: PNode): string {
  return lval(n);
}
